import{_ as u,o as s,c as t,b as e,F as o,e as h,u as b,f,g as r,a as x,t as y,r as v}from"./app.6693f877.js";import{p as w}from"./dean.2bcf0097.js";const _={name:"About",setup(){const n=b();return{socialLink:f().value.globalData.socialLink,page:n,portraitSrc:w}}},k={id:"about",class:"block pt-10 pb-20 bg-gray-100"},I={class:"container max-w-[900px]"},S={class:"mx-auto flex flex-col items-center gap-y-5 md:gap-y-0 md:flex-row md:justify-between md:gap-x-12"},L={class:"order-2"},j=e("h3",{class:"text-6xl font-cursive pt-3 mb-10"},"About",-1),A=r('<h1 class="text-3xl font-bold">Hi, I am <span class="text-blue-500">Dean</span>.</h1><p class="mt-6 text-base leading-loose"> I moved from product design into software engineering, with both design thinking and hands-on engineering in my toolkit. Because I understand product, interface, and technology together, I care about more than \u201Cfeature done\u201D\u2014I weigh user experience, interaction flow, and overall product quality. That mix helps me bridge design and engineering when gathering requirements, and when complex problems show up, I reason from product, user, and system angles to pick sensible paths. </p><p class="mt-4 text-base leading-loose"> I am solid on foundational web tech\u2014<span class="text-blue-500">HTML, CSS, JavaScript, PHP</span>\u2014and work comfortably with mainstream stacks such as <span class="text-blue-500">Node.js, Laravel, Vue, and React</span>. I have freelanced, taught interactive interface design at university, and advised several companies, building cross-domain project experience and communication habits. Those years mean I do not only implement\u2014I can stand at the intersection of product, design, technology, and business needs and propose fuller solutions. </p><p class="mt-4 text-base leading-loose"> Today I am a frontend lead at a game company, focused on <span class="text-blue-500">Cocos Creator</span> while contributing to technical planning, project management, and staffing. I am not only a frontend engineer but an <strong>integration core</strong> for the team: work spans the full delivery chain\u2014game frontend, shared assets, configuration, versioning, deployments, and release notes\u2014not just a single feature. From landing requirements and syncing across projects to pushing releases and curating docs, my job is to move work to a state where it can ship stably, not merely \u201Cbuilt.\u201D </p><p class="mt-4 text-base leading-loose"> Where I add value: <strong>cross-project integration</strong>, propagating the same needs, fixes, and shared logic quickly across games and modules to cut rework and misses; <strong>delivery and release</strong>, staying on top of STG, REL, and PROD state, deploy outcomes, S3 backups, and release notes so outcomes land reliably; and <strong>systems thinking and collaboration</strong>, operating across frontend implementation, backend protocols, resource setup, and team process\u2014linking development, deployment, documentation, and cross-functional conversation to keep projects moving. </p><p class="mt-4 text-base leading-loose"> Alongside frontend and delivery, I invest in <strong>AI workflows and tooling</strong>\u2014for example <strong>proposal-generator</strong>, GitLab-based work-report automation, ByteHouse analytics flows, and packaged <strong>skills / agent</strong> capabilities. This is not casual tool use; it turns everyday dev, data queries, proposals, and reporting into repeatable, retainable, extensible AI collaboration. My role expands toward someone who advances technical delivery, process design, and tooling\u2014not only code. </p><p class="mt-4 text-base leading-loose"> Looking ahead, I want to keep growing in frontend architecture, cross-project integration, technical leadership, and AI workflows\u2014becoming a leader who not only implements but aligns resources, improves process, and amplifies what the whole team can ship. </p>',7),D=r('<h1 class="text-3xl font-bold">Hi, \u6211\u662F <span class="text-blue-500">\u6B23\u8FEA</span></h1><p class="mt-6 text-base leading-loose"> \u6211\u662F\u4E00\u4F4D\u5F9E\u7522\u54C1\u8A2D\u8A08\u9818\u57DF\u8F49\u8077\u70BA\u8EDF\u9AD4\u5DE5\u7A0B\u5E2B\u7684\u6280\u8853\u5DE5\u4F5C\u8005\uFF0C\u5177\u5099\u8A2D\u8A08\u601D\u7DAD\u8207\u5DE5\u7A0B\u5BE6\u4F5C\u7684\u96D9\u91CD\u80CC\u666F\u3002\u56E0\u70BA\u540C\u6642\u7406\u89E3\u7522\u54C1\u3001\u4ECB\u9762\u8207\u6280\u8853\uFF0C\u6211\u5728\u958B\u767C\u904E\u7A0B\u4E2D\u4E0D\u53EA\u95DC\u6CE8\u529F\u80FD\u662F\u5426\u5B8C\u6210\uFF0C\u4E5F\u91CD\u8996\u4F7F\u7528\u8005\u9AD4\u9A57\u3001\u4E92\u52D5\u6D41\u7A0B\u8207\u6574\u9AD4\u7522\u54C1\u54C1\u8CEA\u3002\u9019\u6A23\u7684\u80CC\u666F\u8B93\u6211\u5728\u8A2D\u8A08\u8207\u5DE5\u7A0B\u4E4B\u9593\u80FD\u66F4\u6709\u6548\u5730\u6574\u5408\u9700\u6C42\uFF0C\u4E26\u5728\u9762\u5C0D\u8907\u96DC\u6280\u8853\u554F\u984C\u6642\uFF0C\u5F9E\u7522\u54C1\u3001\u4F7F\u7528\u8005\u8207\u7CFB\u7D71\u4E09\u500B\u89D2\u5EA6\u601D\u8003\u6700\u5408\u9069\u7684\u89E3\u6CD5\u3002 </p><p class="mt-4 text-base leading-loose"> \u6211\u5177\u5099 <span class="text-blue-500">HTML</span>\u3001<span class="text-blue-500">CSS</span>\u3001<span class="text-blue-500">JavaScript</span>\u3001<span class="text-blue-500">PHP</span> \u7B49\u524D\u5F8C\u7AEF\u57FA\u790E\u6280\u8853\u80FD\u529B\uFF0C\u4E26\u719F\u6089 <span class="text-blue-500">Node.js</span>\u3001<span class="text-blue-500">Laravel</span>\u3001<span class="text-blue-500">Vue</span>\u3001<span class="text-blue-500">React</span> \u7B49\u4E3B\u6D41\u6846\u67B6\u3002\u904E\u53BB\u66FE\u64D4\u4EFB Freelancer\u3001\u5927\u5B78\u4E92\u52D5\u4ECB\u9762\u8A2D\u8A08\u8B1B\u5E2B\uFF0C\u4E26\u65BC\u591A\u5BB6\u4F01\u696D\u64D4\u4EFB\u6280\u8853\u9867\u554F\uFF0C\u7D2F\u7A4D\u4E86\u8DE8\u9818\u57DF\u5C08\u6848\u5BE6\u52D9\u8207\u6E9D\u901A\u5354\u8ABF\u7D93\u9A57\u3002\u9019\u4E9B\u7D93\u6B77\u8B93\u6211\u4E0D\u53EA\u662F\u80FD\u5B8C\u6210\u958B\u767C\u5DE5\u4F5C\uFF0C\u4E5F\u80FD\u7AD9\u5728\u7522\u54C1\u3001\u8A2D\u8A08\u3001\u6280\u8853\u8207\u5546\u696D\u9700\u6C42\u7684\u4EA4\u6703\u9EDE\uFF0C\u63D0\u4F9B\u66F4\u5B8C\u6574\u7684\u89E3\u6C7A\u65B9\u6848\u3002 </p><p class="mt-4 text-base leading-loose"> \u76EE\u524D\u6211\u4EFB\u8077\u65BC\u904A\u6232\u516C\u53F8\u64D4\u4EFB\u524D\u7AEF Leader\uFF0C\u4E3B\u8981\u8CA0\u8CAC\u4F7F\u7528 <span class="text-blue-500">Cocos Creator</span> \u9032\u884C\u904A\u6232\u524D\u7AEF\u958B\u767C\uFF0C\u540C\u6642\u53C3\u8207\u6280\u8853\u898F\u5283\u3001\u5C08\u6848\u7BA1\u7406\u8207\u4EBA\u54E1\u8ABF\u5EA6\u3002\u6211\u7684\u89D2\u8272\u4E0D\u53EA\u662F\u524D\u7AEF\u5DE5\u7A0B\u5E2B\uFF0C\u66F4\u662F\u5718\u968A\u4E2D\u7684<strong>\u6574\u5408\u6838\u5FC3</strong>\u3002\u5DE5\u4F5C\u5167\u5BB9\u4E0D\u4FB7\u9650\u65BC\u55AE\u4E00\u904A\u6232\u529F\u80FD\u958B\u767C\uFF0C\u800C\u662F\u6A6B\u8DE8\u904A\u6232\u524D\u7AEF\u3001\u5171\u7528\u8CC7\u6E90\u3001\u8A2D\u5B9A\u914D\u7F6E\u3001\u7248\u672C\u63A7\u7BA1\u3001\u90E8\u7F72\u6D41\u7A0B\u8207 Release Note \u7B49\u5B8C\u6574\u4EA4\u4ED8\u93C8\u3002\u5F9E\u9700\u6C42\u843D\u5730\u3001\u8DE8\u5C08\u6848\u540C\u6B65\u3001\u4E0A\u7248\u63A8\u9032\u5230\u6587\u4EF6\u6574\u7406\uFF0C\u6211\u8CA0\u8CAC\u7684\u4E0D\u53EA\u662F\u628A\u529F\u80FD\u505A\u51FA\u4F86\uFF0C\u800C\u662F\u628A\u9700\u6C42\u771F\u6B63\u63A8\u9032\u5230\u53EF\u7A69\u5B9A\u4E0A\u7DDA\u7684\u72C0\u614B\u3002 </p><p class="mt-4 text-base leading-loose"> \u6211\u7684\u50F9\u503C\u4E3B\u8981\u9AD4\u73FE\u5728\u5E7E\u500B\u9762\u5411\u3002\u9996\u5148\u662F<strong>\u8DE8\u5C08\u6848\u6574\u5408\u80FD\u529B</strong>\uFF0C\u80FD\u5920\u5C07\u540C\u4E00\u985E\u9700\u6C42\u3001\u4FEE\u6B63\u6216\u5171\u7528\u908F\u8F2F\u5FEB\u901F\u540C\u6B65\u5230\u591A\u500B\u904A\u6232\u8207\u5171\u7528\u6A21\u7D44\uFF0C\u964D\u4F4E\u91CD\u5DE5\u8207\u907A\u6F0F\u98A8\u96AA\u3002\u5176\u6B21\u662F<strong>\u4EA4\u4ED8\u8207\u4E0A\u7248\u80FD\u529B</strong>\uFF0C\u6211\u4E0D\u53EA\u53C3\u8207\u529F\u80FD\u5BE6\u4F5C\uFF0C\u4E5F\u80FD\u638C\u63E1 STG\u3001REL\u3001PROD \u7684\u7248\u672C\u72C0\u614B\u3001\u90E8\u7F72\u7D50\u679C\u3001S3 \u5099\u4EFD\u8207 Release Note\uFF0C\u78BA\u4FDD\u5718\u968A\u6210\u679C\u80FD\u7A69\u5B9A\u4EA4\u4ED8\u3002\u6B64\u5916\uFF0C\u6211\u4E5F\u5177\u5099<strong>\u7CFB\u7D71\u7406\u89E3\u8207\u5354\u4F5C\u80FD\u529B</strong>\uFF0C\u80FD\u540C\u6642\u7AD9\u5728\u524D\u7AEF\u5BE6\u4F5C\u3001\u5F8C\u7AEF\u5354\u8B70\u3001\u8CC7\u6E90\u914D\u7F6E\u8207\u5718\u968A\u6D41\u7A0B\u7684\u4EA4\u754C\u9EDE\uFF0C\u5728\u958B\u767C\u3001\u90E8\u7F72\u3001\u6587\u4EF6\u8207\u8DE8\u90E8\u9580\u6E9D\u901A\u4E4B\u9593\u5EFA\u7ACB\u9023\u7D50\uFF0C\u6210\u70BA\u63A8\u52D5\u5C08\u6848\u524D\u9032\u7684\u91CD\u8981\u89D2\u8272\u3002 </p><p class="mt-4 text-base leading-loose"> \u9664\u4E86\u524D\u7AEF\u8207\u4EA4\u4ED8\u5DE5\u4F5C\u4E4B\u5916\uFF0C\u6211\u9032\u4E00\u6B65\u53C3\u8207 AI workflow \u8207\u5DE5\u5177\u5316\u76F8\u95DC\u5C08\u6848\uFF0C\u4F8B\u5982 <strong>proposal-generator</strong>\u3001GitLab \u5DE5\u4F5C\u5F59\u5831\u81EA\u52D5\u5316\u3001ByteHouse \u5206\u6790\u6D41\u7A0B\uFF0C\u4EE5\u53CA skills\uFF0Fagent \u80FD\u529B\u5C01\u88DD\u3002\u9019\u4E9B\u5DE5\u4F5C\u4E0D\u53EA\u662F\u4F7F\u7528 AI \u5DE5\u5177\uFF0C\u800C\u662F\u5C07\u5718\u968A\u65E5\u5E38\u958B\u767C\u3001\u8CC7\u6599\u67E5\u8A62\u3001\u63D0\u6848\u8207\u5831\u544A\u6D41\u7A0B\uFF0C\u8F49\u5316\u70BA\u53EF\u91CD\u8907\u57F7\u884C\u3001\u53EF\u6C89\u6FB1\u3001\u53EF\u64F4\u5145\u7684 AI \u5354\u4F5C\u80FD\u529B\u3002\u9019\u8B93\u6211\u5728\u5718\u968A\u4E2D\u7684\u5B9A\u4F4D\uFF0C\u4E0D\u53EA\u662F\u524D\u7AEF\u5DE5\u7A0B\u5E2B\uFF0C\u800C\u662F\u80FD\u540C\u6642\u63A8\u52D5\u6280\u8853\u4EA4\u4ED8\u3001\u6D41\u7A0B\u898F\u5283\u8207\u5DE5\u5177\u6F14\u9032\u7684\u591A\u529F\u80FD\u6574\u5408\u4EBA\u624D\u3002 </p><p class="mt-4 text-base leading-loose"> \u672A\u4F86\uFF0C\u6211\u5E0C\u671B\u6301\u7E8C\u6DF1\u5316\u81EA\u5DF1\u5728\u524D\u7AEF\u67B6\u69CB\u3001\u8DE8\u5C08\u6848\u6574\u5408\u3001\u6280\u8853\u7BA1\u7406\u8207 AI workflow \u4E0A\u7684\u80FD\u529B\uFF0C\u6210\u70BA\u4E0D\u53EA\u61C2\u6280\u8853\u5BE6\u4F5C\uFF0C\u4E5F\u80FD\u6574\u5408\u5718\u968A\u8CC7\u6E90\u3001\u512A\u5316\u6D41\u7A0B\u4E26\u653E\u5927\u5718\u968A\u7522\u51FA\u7684\u6280\u8853\u9818\u5C0E\u8005\u3002 </p>',7),H={class:"flex gap-[20px] mt-10 justify-center md:justify-start"},R=["href"],T={class:"w-8 h-8"},C={class:"shrink-0 flex-grow order-1 md:order-2"},N=["src"];function P(n,l,B,a,q,V){const i=v("svg-icon");return s(),t("section",k,[e("div",I,[e("div",S,[e("div",L,[j,a.page.lang==="en-US"?(s(),t(o,{key:0},[A],64)):(s(),t(o,{key:1},[D],64)),e("div",H,[(s(!0),t(o,null,h(a.socialLink,({sub:c,url:d,icon:p,color:g},m)=>(s(),t("a",{key:m,href:d,target:"_blank",class:"flex flex-col items-center md:opacity-70 md:hover:opacity-100 transition-opacity duration-500 ease-in-out"},[e("div",T,[x(i,{name:p,color:g},null,8,["name","color"])]),e("p",null,y(c),1)],8,R))),128))])]),e("div",C,[e("img",{class:"rounded-full w-full max-w-[130px] md:max-w-[200px]",src:a.portraitSrc,alt:"Dean",loading:"lazy"},null,8,N)])])])])}var E=u(_,[["render",P],["__file","About.vue"]]);export{E as default};
